solution.replace:
// Runner config files (JSON). The result of parsing is meant for resolveConfig({ file }).
//
// Format 2 (current):
//   {"version": 2,
//    "runner": {"concurrency": 8, "defaultTimeout": "2m"},
//    "retry": {"maxAttempts": 5},
//    "api": {"port": 9000},
//    "logging": {"level": "debug"}}
// Format 1 (deprecated, no "version" key):
//   {"concurrency": 8, "timeout": "2m", "maxAttempts": 5, "port": 9000, "logLevel": "debug"}
import type { LogLevel, RunnerConfig } from "./config.ts";
import { parseDuration } from "./duration.ts";

export class ConfigFileError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ConfigFileError";
  }
}

export interface ParseOptions {
  warn?: (message: string) => void;
}

const V1_KEYS = ["concurrency", "timeout", "maxAttempts", "port", "logLevel"];
const V2_SECTIONS: Array<[string, string[]]> = [
  ["runner", ["concurrency", "defaultTimeout"]],
  ["retry", ["maxAttempts"]],
  ["api", ["port"]],
  ["logging", ["level"]],
];
// format-1 key -> [format-2 section, key]
const V1_TO_V2: Record<string, [string, string]> = {
  concurrency: ["runner", "concurrency"],
  timeout: ["runner", "defaultTimeout"],
  maxAttempts: ["retry", "maxAttempts"],
  port: ["api", "port"],
  logLevel: ["logging", "level"],
};

type Sections = Record<string, Record<string, unknown>>;

function integer(value: unknown, key: string): number {
  if (typeof value !== "number" || !Number.isInteger(value)) throw new ConfigFileError(`${key} must be an integer`);
  return value;
}

function duration(value: unknown, key: string): number {
  if (typeof value !== "string" && typeof value !== "number") throw new ConfigFileError(`${key} must be a duration`);
  try {
    return parseDuration(value);
  } catch (error) {
    throw new ConfigFileError(`${key}: ${(error as Error).message}`);
  }
}

function parseObject(text: string): Record<string, unknown> {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch (error) {
    throw new ConfigFileError(`invalid JSON: ${(error as Error).message}`);
  }
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new ConfigFileError("config file must contain a JSON object");
  }
  return raw as Record<string, unknown>;
}

function formatOf(data: Record<string, unknown>): 1 | 2 {
  if (!("version" in data)) return 1;
  if (data.version === 2) return 2;
  throw new ConfigFileError(`unsupported config file version ${JSON.stringify(data.version)} (expected 2)`);
}

function sectionsFromV1(data: Record<string, unknown>): Sections {
  const unknown = Object.keys(data).filter((key) => !V1_KEYS.includes(key));
  if (unknown.length > 0) throw new ConfigFileError(`unknown config key(s): ${unknown.join(", ")}`);
  const sections: Sections = {};
  for (const key of V1_KEYS) {
    if (data[key] === undefined) continue;
    const [section, name] = V1_TO_V2[key];
    sections[section] = { ...sections[section], [name]: data[key] };
  }
  return sections;
}

function sectionsFromV2(data: Record<string, unknown>): Sections {
  const sections: Sections = {};
  const known = new Map(V2_SECTIONS);
  for (const [section, value] of Object.entries(data)) {
    if (section === "version") continue;
    const keys = known.get(section);
    if (!keys) throw new ConfigFileError(`unknown config section: ${section}`);
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      throw new ConfigFileError(`${section} must be an object`);
    }
    const unknown = Object.keys(value).filter((key) => !keys.includes(key));
    if (unknown.length > 0) throw new ConfigFileError(`unknown config key(s): ${unknown.map((k) => `${section}.${k}`).join(", ")}`);
    sections[section] = value as Record<string, unknown>;
  }
  return sections;
}

function toConfig(sections: Sections): Partial<RunnerConfig> {
  const out: Partial<RunnerConfig> = {};
  const runner = sections.runner ?? {};
  if (runner.concurrency !== undefined) out.concurrency = integer(runner.concurrency, "runner.concurrency");
  if (runner.defaultTimeout !== undefined) out.defaultTimeoutMs = duration(runner.defaultTimeout, "runner.defaultTimeout");
  const retry = sections.retry ?? {};
  if (retry.maxAttempts !== undefined) out.maxAttempts = integer(retry.maxAttempts, "retry.maxAttempts");
  const api = sections.api ?? {};
  if (api.port !== undefined) out.apiPort = integer(api.port, "api.port");
  const logging = sections.logging ?? {};
  if (logging.level !== undefined) out.logLevel = String(logging.level).toLowerCase() as LogLevel;
  return out;
}

function toV2Document(sections: Sections): Record<string, unknown> {
  const doc: Record<string, unknown> = { version: 2 };
  for (const [section, keys] of V2_SECTIONS) {
    const values: Record<string, unknown> = {};
    for (const key of keys) {
      if (sections[section]?.[key] !== undefined) values[key] = sections[section][key];
    }
    if (Object.keys(values).length > 0) doc[section] = values;
  }
  return doc;
}

export function parseConfigFile(text: string, options: ParseOptions = {}): Partial<RunnerConfig> {
  const data = parseObject(text);
  if (formatOf(data) === 2) return toConfig(sectionsFromV2(data));
  const sections = sectionsFromV1(data);
  const config = toConfig(sections);
  (options.warn ?? console.warn)("config file format 1 is deprecated; convert it to version 2 with upgradeConfigFile");
  return config;
}

// Rewrites a config file as format 2 (pretty-printed, trailing newline).
export function upgradeConfigFile(text: string): string {
  const data = parseObject(text);
  const sections = formatOf(data) === 2 ? sectionsFromV2(data) : sectionsFromV1(data);
  toConfig(sections);
  return JSON.stringify(toV2Document(sections), null, 2) + "\n";
}
